/**
 * The shared physically based material library.
 *
 * Every GLB material name is mapped to one of these through
 * `src/data/assets.ts`, so a hand-authored Blender export with the same
 * material names drops straight into the same look.
 *
 * Nothing here is a flat colour: every opaque surface carries albedo,
 * roughness and normal detail generated by `src/lib/surface/`, and the leaf
 * materials are alpha-masked cards with a shared wind shader patch.
 */

import * as THREE from 'three'
import { surfaceTextures, type TextureSet } from './textures'

