/* ------------------------------------------------------------------- utils */

export function emissiveMaterial(color: string, intensity = 1, opacity = 1) {
  return memo(`emissive-${color}-${intensity}-${opacity}`, () =>
    new THREE.MeshStandardMaterial({
      color: new THREE.Color(color),
      emissive: new THREE.Color(color),
      emissiveIntensity: intensity,
      roughness: 0.4,
      metalness: 0,
      transparent: opacity < 1,
      opacity,
    }),
  )
}

export function flatMaterial(color: string, opacity = 1) {
  return memo(`flat-${color}-${opacity}`, () =>
    new THREE.MeshBasicMaterial({ color: new THREE.Color(color), transparent: opacity < 1, opacity }),
  )
}

/** Soft radial blob used as a fake contact shadow / pooling decal. */
let radialTexture: THREE.Texture | null = null
export function decalMaterial(color = '#000000', opacity = 0.5) {
  return memo(`decal-${color}-${opacity}`, () => {
    if (!radialTexture) {
      const size = 128
      const data = new Uint8Array(size * size * 4)
      for (let y = 0; y < size; y++) {
        for (let x = 0; x < size; x++) {
          const dx = (x / size) * 2 - 1
          const dy = (y / size) * 2 - 1
          const d = Math.min(1, Math.sqrt(dx * dx + dy * dy))
          const i = (y * size + x) * 4
          data[i] = 255
          data[i + 1] = 255
          data[i + 2] = 255
          data[i + 3] = Math.round(Math.pow(1 - d, 2.4) * 255)
        }
      }
      radialTexture = new THREE.DataTexture(data, size, size, THREE.RGBAFormat)
      radialTexture.colorSpace = THREE.SRGBColorSpace
      radialTexture.needsUpdate = true
    }
    return new THREE.MeshBasicMaterial({
      color: new THREE.Color(color),
      alphaMap: radialTexture,
      transparent: true,
      opacity,
      depthWrite: false,
    })
  })
}

/** India map states: natural stone, not neon. */
export function stateBaseMaterial(size: 256 | 512 = 256) {
  return fromSurface('state-base', 'stone', size, {
    color: 0x8d8571,
    roughness: 0.82,
    metalness: 0.12,
    envMapIntensity: 0.55,
    normalScale: 0.6,
  })
}

/* -------------------------------------------------------------- key mapping */

export type MaterialKey = string

/**
 * GLB material name → shared material.
 *
 * The GLB generator uses the same names as an artist would in Blender, so a
 * real export needs no code changes.
 */
export function materialForKey(
  key: string,
  quality: { textureSize: 256 | 512; shade?: boolean },
): THREE.Material {
  const size = quality.textureSize
  switch (key) {
    case 'concrete':
      return concreteMaterial('mid', 1, size)
    case 'darkConcrete':
      return concreteMaterial('dark', 1, size)
    case 'lightConcrete':
      return concreteMaterial('light', 1, size)
    case 'render':
      return renderMaterial(size, 'render')
    case 'renderWarm':
      return renderMaterial(size, 'renderWarm')
    case 'renderOld':
      return renderMaterial(size, 'renderOld')
    case 'stone':
      return stoneMaterial(size, false)
    case 'stoneBlock':
      return stoneMaterial(size, true)
    case 'brick':
      return brickMaterial(size)
    case 'asphalt':
      return asphaltMaterial(size)
    case 'roadPaint':
      return roadPaintMaterial(size)
    case 'asphaltPatch':
      return asphaltPatchMaterial(size)
    case 'soil':
      return soilMaterial(size, false)
    case 'soilDry':
      return soilMaterial(size, true)
    case 'gravel':
      return gravelMaterial(size)
    case 'grass':
      return grassMaterial(size)
    case 'sand':
      return plain('sand', { color: new THREE.Color(PALETTE.sand), roughness: 1, metalness: 0 })
    case 'wood':
    case 'bark':
      return woodMaterial(size)
    case 'metal':
      return metalMaterial('brushed', 1, size)
    case 'darkMetal':
      return metalMaterial('dark', 1, size)
    case 'rim':
      return metalMaterial('bright', 1, size)
    case 'rust':
      return metalMaterial('rust', 1, size)
    case 'glass':
      return glassMaterial(PALETTE.glass, 0.34)
    case 'glassDark':
      return glassMaterial(PALETTE.glassDark, 0.55, 0.1)
    case 'panelDark':
      return panelMaterial()
    case 'plastic':
      return plasticMaterial('#5c625a')
    case 'paintA':
      return paintMaterial(PALETTE.paintA, 0.24)
    case 'paintB':
      return paintMaterial(PALETTE.paintB, 0.3)
    case 'paintC':
      return paintMaterial(PALETTE.paintC, 0.28)
    case 'paintD':
      return paintMaterial(PALETTE.paintD, 0.32)
    case 'paintMuted':
      return paintMaterial(PALETTE.mutedPaint, 0.55)
    case 'safety':
      return paintMaterial(PALETTE.safety, 0.6)
    case 'rubber':
      return rubberMaterial()
    case 'light':
      return lightMaterial('#f2f0e2', 0.25)
    case 'tail':
      return lightMaterial('#8e1f14', 0.15)
    case 'plate':
      return plasticMaterial('#d8d4c4')
    case 'sack':
      return fromSurface('sack', 'render', size, { color: 0xcfc8b6, roughness: 0.95, metalness: 0 })
    case 'tarp':
      return fromSurface('tarp', 'metalDark', size, { color: 0x44525a, roughness: 0.7, metalness: 0.1 })
    case 'terracotta':
      return plain('terracotta', { color: new THREE.Color(PALETTE.terracotta), roughness: 0.8, metalness: 0 })
    case 'leaf':
      return leafMaterial('leaf', size)
    case 'leafB':
    case 'leafWarm':
      return leafMaterial('leafWarm', size)
    case 'leafDry':
      return leafMaterial('leafDry', size)
    case 'foliage':
      return foliageMaterial(PALETTE.foliage, size)
    case 'foliageB':
      return foliageMaterial(PALETTE.foliageB, size)
    default:
      return concreteMaterial('mid', 1, size)
  }
}

export function disposeMaterials() {
  cache.forEach((material) => material.dispose())
  cache.clear()
}
